import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"九佳","description":"","frontmatter":{"title":"九佳","date":"2026-11-17T00:00:00.000Z","seq":9,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/九佳.md","filePath":"blogs/声律启蒙·上卷/九佳.md"}'),r={name:"blogs/声律启蒙·上卷/九佳.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="九佳" tabindex="-1">九佳 <a class="header-anchor" href="#九佳" aria-label="Permalink to &quot;九佳&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">河对海，汉对淮，赤岸对朱崖。鹭飞对鱼跃，宝钿对金钗。鱼圉圉，鸟喈喈，草履对芒鞋。古贤尝笃厚，时辈喜诙谐。孟训文公谈性善，颜师孔子问心斋。缓抚琴弦，像流莺而并语；斜排筝柱。类过雁之相挨。</p><p class="poem-stanza">丰对俭，等对差，布袄对荆钗。雁行对鱼阵，榆塞对兰崖。挑荠女，采莲娃，菊径对苔阶。诗成六义备，乐奏八音谐。造律吏哀秦法酷，知音人说郑声哇。天欲飞霜，塞上有鸿行已过；云将作雨，庭前多蚁阵先排。</p><p class="poem-stanza">城对市，巷对街，破屋对空阶。桃枝对桂叶，砌蚓对墙蜗。梅可望，橘堪怀，季路对高柴。花藏沽酒市，竹映读书斋。马首不容孤竹扣，车轮终就洛阳埋。朝宰锦衣，贵束乌犀之带；宫人宝髻，宜簪白燕之钗。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
